-- Seed the industry / job-designation lookup tables the profile flow relies on.
-- These rows were missing in production, so the "Current Position" combobox on the
-- candidate create-profile page showed "No job title found for your industry." for
-- every industry (it_software / banking / finance_investment resolve to these rows).
--
-- Idempotent: explicit IDs with ON CONFLICT DO NOTHING so re-running is a no-op and
-- no existing data is dropped or cleared. Insert order respects FKs
-- (seniority_levels + industries before job_designations). The designation sequence
-- is bumped past the seeded IDs at the end.
BEGIN;

INSERT INTO seniority_levels (level_id, level_name, level_order) VALUES
    (1, 'Entry Level', 1),
    (2, 'Junior', 2),
    (3, 'Mid-Level', 3),
    (4, 'Senior', 4),
    (5, 'Lead', 5),
    (6, 'Principal', 6)
ON CONFLICT (level_id) DO NOTHING;

INSERT INTO industries (industry_id, industry_name) VALUES
    (1, 'IT / Software Development'),
    (2, 'Banking'),
    (3, 'Finance & Investment')
ON CONFLICT (industry_id) DO NOTHING;

